import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Bir görseli kırpmak saniyeler sürer. Program kurmazsınız, fotoğrafınız cihazınızdan ayrılmaz ve sonunda temiz bir kırpma indirirsiniz.</p>\n<p>Bu yazı, işlemi beş adımda anlatıyor. İster profil fotoğrafı ister ürün görseli kırpın, adımlar aynıdır.</p>\n<p>Sonunda seçim kutusunu nasıl sürükleyeceğinizi, oranı nasıl seçeceğinizi ve sonucu indirmeden önce nasıl kontrol edeceğinizi öğreneceksiniz.</p>\n<h2 id=\"before-you-start\">Başlamadan önce: önce hedefi seçin</h2>\n<p>Önce görselin nereye gideceğini belirleyin. Profil, afiş, baskı ya da ürün listesi; hedef, oranı belirler.</p>\n<p>Orijinal fotoğrafın bir yedeğini alın. Kırpma geri alınamaz; orijinal güvenlik ağınızdır.</p>\n<p>Hedef boyutları öğrenin. Platformun istediği piksel boyutunu bilmek, kırpmayı doğru yapmanızı sağlar.</p>\n<h2 id=\"step-by-step\">Görsel kırpma beş adımda</h2>\n<p>Önce aracı açın ve görseli yükleyin. Önizlemede fotoğrafın tamamını görün.</p>\n<p>Sonra seçim kutusunu sürükleyin ve oranı seçin. Izgara, konuyu yerleştirmenize yardım eder.</p>\n<p>Son olarak sonucu kontrol edip indirin. Önizlemeyi atlamayın; yanlış kırpma zaman kaybıdır.</p>\n<ol>\n<li>Kırpma aracını açın ve görselinizi yükleyin.</li>\n<li>Seçim kutusunu sürükleyerek kırpılacak alanı belirleyin.</li>\n<li>Oran ön ayarını seçin; profil için 1:1, afiş için 16:9.</li>\n<li>Çıktı boyutlarını ve formatı kontrol edin.</li>\n<li>Kırpılan görseli indirin.</li>\n</ol>\n<h2 id=\"dragging-the-selection-box\">Seçim kutusunu sürüklemek</h2>\n<p>Seçim kutusunun köşelerini sürükleyerek alanı ayarlayın. Kutunun içi kalır; dışı atılır.</p>\n<p>Kutuyu taşımak için ortasından sürükleyin. Konuyu çerçeveye almak için kutuyu kaydırın.</p>\n<p>Küçük ayarlar için köşeleri tek tek sürükleyin. Hassas çerçeve, sabır ister.</p>\n<h2 id=\"choosing-an-aspect-ratio\">Oran ön ayarı seçmek</h2>\n<p>Oran ön ayarları, kutuyu otomatik kilitler. 1:1 seçerseniz kutu her zaman kare kalır.</p>\n<p>Profil için 1:1, kapak için 16:9, dikey gönderi için 4:5 kullanın. Platform kurallarını öğrenin.</p>\n<p>Hiçbir ön ayar uymuyorsa serbest kırpma kullanın. Serbest modda kutu her biçime girebilir.</p>\n<h2 id=\"using-the-grid\">Üçte bir kuralı ızgarasını kullanmak</h2>\n<p>Izgara, kırpma alanını dokuz eşit parçaya böler. Konuyu çizgilerin kesişimine koyun.</p>\n<p>Bu kural, fotoğrafı dengeli gösterir. Göz, kesişim noktalarına doğal olarak odaklanır.</p>\n<p>Kuralı her zaman izlemek zorunda değilsiniz. Merkezdeki konu da güçlü olabilir; ızgara yalnızca bir rehberdir.</p>\n<h2 id=\"zooming-for-detail\">Hassas çerçeve için yakınlaştırma</h2>\n<p>Yakınlaştırma küçük ayrıntıyı tam kırpmanızı sağlar. Yüzü ya da ürünü tam çerçeveye alın.</p>\n<p>Yakınlaştırırken çözünürlüğe dikkat edin. Fazla yakınlaştırma pikselleri büyütür ve bulanıklık yapar.</p>\n<p>Hassas çerçeve için ızgarayı kullanın. Çizgiler konunun nereye oturduğunu gösterir.</p>\n<h2 id=\"checking-dimensions\">İndirmeden önce çıktı boyutlarını kontrol etmek</h2>\n<p>Çıktı boyutları, kırpılan alanın piksel sayısıdır. Hedef platformun istediği boyutla karşılaştırın.</p>\n<p>Kırpılan alan hedeften küçükse kaynak yetersizdir. Daha yüksek çözünürlüklü kaynak kullanın.</p>\n<p>Boyutları indirmeden önce kontrol edin. Küçük indirilen görsel, platformda bulanık görünür.</p>\n<h2 id=\"choosing-export-format\">Dışa aktarma formatı ve kalite seçmek</h2>\n<p>Kırpılan fotoğrafları JPG olarak kaydedin. Dosya hafifler ve her programda açılır.</p>\n<p>Saydam alanlı görseller PNG ister. JPG, saydamlığı koruyamaz.</p>\n<p>Kaliteyi yüzde 85-90 tutun. Bu aralık, görünür fark yaratmadan dosyayı küçültür.</p>\n<h2 id=\"cropping-screenshots\">Ekran görüntüsü kırpmak</h2>\n<p>Ekran görüntülerinde gereksiz araç çubuklarını kırpın. Yalnızca ilgili bölüm kalmalı.</p>\n<p>Yazıları kesmemeye dikkat edin. Kırpma çizgisi metnin üzerinden geçmemelidir.</p>\n<p>Ekran görüntüleri için PNG kullanın. Kayıpsız yapı, yazıları keskin tutar.</p>\n<h2 id=\"cropping-on-mobile\">Telefon ve tablette kırpmak</h2>\n<p>Kırpma aracını telefon tarayıcısında açın, görseli yükleyin ve kutuyu parmağınızla sürükleyin.</p>\n<p>Telefonda küçük ayarlar zordur. Hassas kırpma için bilgisayarı tercih edin.</p>\n<p>Telefon galerisinin kendi kırpma özelliği de vardır. Hızlı düzeltmeler için galeri yeterlidir.</p>\n<h2 id=\"troubleshooting\">Yaygın kırpma sorunlarını çözmek</h2>\n<p>Kırpılan görsel bulanıksa kaynak küçüktür. Daha yüksek çözünürlüklü kaynak kullanın.</p>\n<p>Oran kilitlenmiyorsa ön ayarı kontrol edin. Serbest modda kutu her biçime girebilir.</p>\n<p>Seçim kutusu kayıyorsa sayfayı yenileyin. Tarayıcı sorunu, genellikle yenilemeyle çözülür.</p>\n<h2 id=\"quick-tips\">Daha iyi kırpmalar için hızlı ipuçları</h2>\n<p>Önce hedefi belirleyin. Hedef, oranı ve boyutu belirler.</p>\n<p>Izgara kullanın. Konuyu çizgilerin kesişimine koyun.</p>\n<p>Önizlemeyi atlamayın. Birkaç saniyelik kontrol, yanlış kırpmayı önler.</p>\n<h2 id=\"cropping-product-photos\">Ürün fotoğraflarını kırpmak</h2>\n<p>Ürün fotoğraflarında ürünü merkeze alın. Arka plan sade olmalıdır.</p>\n<p>Tüm ürün görsellerinde aynı oranı kullanın. Tutarlı liste, mağazada profesyonel görünür.</p>\n<p>Ürünü kesmemeye dikkat edin. Kırpma çizgisi, ürünün kenarından geçmemelidir.</p>\n<h2 id=\"cropping-for-email\">E-posta için görsel kırpmak</h2>\n<p>E-posta görselleri küçük olmalıdır. Gereksiz kenarları kırpın; dosya hafifler.</p>\n<p>Görselin konusunu merkeze alın. E-posta istemcileri görseli kırpabilir; kenarlar risklidir.</p>\n<p>İmzadaki logo için kare kırpma kullanın. Küçük ve net olmalıdır.</p>\n<h2 id=\"cropping-and-accessibility\">Kırpma ve erişilebilirlik</h2>\n<p>Kırpma, önemli ayrıntıyı kesmemelidir. Görseldeki metin, kırpmadan sonra da okunmalıdır.</p>\n<p>Alternatif metin ekleyin. Görsel yüklenemezse okur, metinden ne olduğunu anlar.</p>\n<p>Renk körü okurları düşünün. Kırpma, renk bilgisini kaybettirmemelidir.</p>\n<h2 id=\"saving-crop-presets\">Tekrarlanan kırpmalarla zaman kazanmak</h2>\n<p>Aynı oranı sürekli kullanıyorsanız ön ayarı kaydedin. Her seferinde yeniden ayarlamak zaman kaybıdır.</p>\n<p>Toplu kırpmada aynı oranı kullanın. Tutarlı sonuçlar, iş akışını hızlandırır.</p>\n<p>Ön ayarları not edin. Ekip, aynı oranları kullanmalıdır.</p>\n<p>Adım adım ilerleyin ve her görseli indirmeden önce kontrol edin. Kılavuzun tamamı için <a href=\"/tr/blog/gorsel-kirp-rehberi\">Görsel kırpıcı kılavuzuna</a> bakın; oranlar için <a href=\"/tr/blog/gorsel-kirp-oranlari-aciklandi\">görsel kırpma oranları</a> yazısı yardımcı olur. Döndürme için <a href=\"/tr/gorsel-dondur-cevir\">görsel döndürme ve çevirme</a> hazırdır; araç ise <a href=\"/tr/gorsel-kirp\">görsel kırpıcı</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Instagram için bir görseli kare olarak nasıl kırparım?","answer":"Oran ön ayarından 1:1'i seçin; seçim kutusu kare olarak kilitlenir. Konuyu merkeze alın ve kutuyu sürükleyerek çerçeveyi ayarlayın. Instagram kareyi daireye çevirmez ama profil fotoğrafı daire olur; önemli öğeleri merkeze koyun."},{"question":"Hiçbir uygulama kurmadan fotoğraf kırpabilir miyim?","answer":"Evet. Kırpma aracı tamamen tarayıcıda çalışır; program kurmanız gerekmez. Görseli yükleyin, seçim kutusunu sürükleyin ve indirin. Dosyanız cihazınızdan ayrılmaz."},{"question":"Kırpılan ekran görüntüsünü indirmek için en iyi format hangisi?","answer":"PNG en iyisidir; kayıpsız yapı yazıları keskin tutar. Fotoğraflar için JPG kullanın. Ekran görüntülerinde metin kritikse PNG'yi tercih edin."},{"question":"Fotoğrafın kenarındaki bir kişiyi ya da nesneyi nasıl kırparım?","answer":"Seçim kutusunu, istenmeyen öğe dışarıda kalacak biçimde sürükleyin. Kutunun kenarı, kişinin yüzünden geçmemelidir. Gerekirse kutuyu küçültün; önemli öğeleri çerçeveye alın."},{"question":"Kırpılan görselim yükleyince neden bulanık görünüyor?","answer":"Çünkü kırpılan alan, hedefin istediği boyuttan küçüktür. Küçük kaynaktan kırpılan görsel büyütülünce bulanıklaşır. Daha yüksek çözünürlüklü kaynak kullanın ve çıktı boyutlarını indirmeden önce kontrol edin."},{"question":"İndirdikten sonra bir kırpmayı geri alabilir miyim?","answer":"Hayır, indirilen kırpma geri alınamaz; atılan pikseller dosyada yoktur. Bu yüzden orijinal fotoğrafı saklayın. Orijinal dururken istediğiniz zaman yeniden kırpabilirsiniz."}];
